"""Generate js/config.js from config.json (the single source of balance numbers).

Run from anywhere:  python3 python/build_config.py
"""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "config.json"
OUT = ROOT / "js" / "config.js"


def main() -> None:
    config = json.loads(SRC.read_text(encoding="utf-8"))
    body = json.dumps(config, indent=2)
    OUT.write_text(
        "// GENERATED by python/build_config.py from config.json. Edit config.json, not this file.\n"
        f"export const CONFIG = {body};\n",
        encoding="utf-8",
    )
    print(f"Wrote {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
